/* ============ Kadın yüzü 2.0: referans görselden kesilmiş katmanlı yüz (ten rengi değişebilir) ============ */
const FEMIMG={sil:'data:image/webp;base64,'+'',det:'data:image/webp;base64,'+''};
/* yerleşim: görsel kırpımı 605x860 px, ölçek .055 → 33.3x47.3 birim; kafa üstü y=13, merkez x=50 */
function femHead(id,skin,age,sad){const X=33.4,Y=12,W=33.3,H=47.3;
 let s=`<defs><mask id="${id}fm"><image href="${FEMIMG.sil}" x="${X}" y="${Y}" width="${W}" height="${H}"/></mask></defs>`;
 s+=`<rect x="${X}" y="${Y}" width="${W}" height="${H}" fill="${skin}" mask="url(#${id}fm)"/>`;
 s+=`<image href="${FEMIMG.det}" x="${X}" y="${Y}" width="${W}" height="${H}"/>`;
 if(sad)s+=`<path d="M46.6 44.6 Q50 43.2 53.4 44.6" stroke="#6a2f33" stroke-width=".7" fill="none" stroke-linecap="round" opacity=".7"/>`;
 if(age>=50)s+=`<path d="M43 23.4 Q47 22.6 50 23.4 Q53 22.6 57 23.4 M41.6 35.6 L42.6 36.4 M58.4 35.6 L57.4 36.4" stroke="${shade(skin,-40)}" stroke-width=".5" fill="none" opacity=".6"/>`;
 return s}
{const _av=avatarSVG2;avatarSVG2=function(L,age,opts){if(L.g!=='k')return _av(L,age,opts);
  const skin=SKINS[L.skin],id='k'+(++uid);let hc=HCOL[L.hairColor];
  if(age>=58&&!['gri','beyaz'].includes(L.hairColor))hc=age>=72?HCOL.beyaz:HCOL.gri;
  const adult=age>=16,o=opts.jail?'mahkum':L.outfit,accs=adult&&!opts.jail?L.acc:(opts.jail&&L.acc.includes('yara')?['yara']:[]);
  const sad=opts.mood!==undefined&&opts.mood<30;
  const G=x=>`<g stroke="${OL2}" stroke-width=".8" stroke-linejoin="round">${x}</g>`;
  let s=`<svg viewBox="14 2 72 79.2" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" style="--sk:${skin}">`;
  s+=G(hair2Back(L.hair,hc)+hairMBack(L.hair,hc));
  /* boyun görselin içinde; boyun dövmesi */
  if(accs.some(a=>a==='boyun'||a==='boyun2'||a==='boyun3'))s+=`<defs><clipPath id="${id}nk"><path d="M44 44 Q43.6 50 43.4 57 Q50 60 56.6 57 Q56.4 50 56 44Z"/></clipPath></defs><g clip-path="url(#${id}nk)"><g transform="translate(50 1) scale(.9 1) translate(-50 0)">${neckTat(accs)}</g></g>`;
  /* gövde: kadın için daha dar omuz */
  s+=`<g transform="translate(50 0) scale(.88 1) translate(-50 0)">`+tat2Neck(accs,id)+G(bodyM(o,(L.oc||{})[o]))+`</g>`;
  ['zincir','kartal','bayrak'].forEach(a=>{if(accs.includes(a))s+=`<g transform="translate(50 0) scale(.88 1) translate(-50 0)">${acc2(a)}</g>`});
  s+=femHead(id,skin,age,sad);
  s+=G(hair2(L.hair,hc)+hairM(L.hair,hc));
  if(age>=40&&age<58&&!['kel','asker'].includes(L.hair)&&!['gri','beyaz'].includes(L.hairColor))s+=`<path d="M37.8 30 Q37.4 25 38.6 21.6 M62.2 30 Q62.6 25 61.4 21.6" stroke="#c4c4c4" stroke-width="1.4" opacity=".6" fill="none" stroke-linecap="round"/>`;
  ['gozyasi','kasust','yildiz','elmacikgul','cizgi3','alinyazi','kaskesik','altindis','kupe','yara','gozluk','puro','fotr','kasket'].forEach(a=>{if(accs.includes(a))s+=acc2(a)});
  {const jw=opts.jw||[];if(adult&&!opts.jail&&jw.length){
    if(jw.includes('saat'))s+=`<rect x="13.6" y="100" width="9" height="3" rx=".8" fill="#c9a24a" stroke="${OL2}" stroke-width=".4"/><circle cx="18.1" cy="101.5" r="1.8" fill="#e8e1cc" stroke="#9c7a2e" stroke-width=".5"/>`;
    if(jw.some(j=>['yuzuk','pirlanta','yakut'].includes(j)))s+=`<circle cx="80.4" cy="104.6" r="1.4" fill="${jw.includes('yakut')?'#b0182a':jw.includes('pirlanta')?'#eef5ff':'#d6a634'}" stroke="#a3801f" stroke-width=".4"/>`}}
  return s+accM(L,accs)+'</svg>'}}
